def count_frequency(lst):
    """
    This function counts the frequency of each element in a list.

    Args:
        lst (list): The input list.

    Returns:
        dict: A dictionary where keys are elements from the list and values are their frequencies.
    """
    frequency_dict = {}
    for element in lst:
        if element in frequency_dict:
            frequency_dict[element] += 1
        else:
            frequency_dict[element] = 1
    return frequency_dict

# Example usage:
numbers = [1, 2, 2, 3, 3, 3, 4, 4, 4, 4]
print(count_frequency(numbers))  # Output: {1: 1, 2: 2, 3: 3, 4: 4}

